#include "PluginEditor.h"
#include "BinaryData.h"

#include <cmath>

namespace { constexpr float pi=3.14159265359f; }
void MadronAudioProcessorEditor::LuckyButton::paintButton(juce::Graphics& g,bool over,bool down){const auto b=getLocalBounds().toFloat().reduced(0.5f);const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);const auto bg=dark_?juce::Colour(0xff0a0a0a):juce::Colours::white;if(active_){for(int i=5;i>0;--i){g.setColour(fg.withAlpha(0.012f*static_cast<float>(6-i)));g.fillRoundedRectangle(b.expanded(static_cast<float>(i*3)),1.0f);}}g.setColour(bg);g.fillRect(b);g.setColour(fg.withAlpha(over?0.95f:0.78f));g.drawRect(b,down?1.4f:1.0f);g.setFont(font_.withHeight(15.0f));g.drawFittedText("I'm Feeling Lucky",getLocalBounds(),juce::Justification::centred,1);}
void MadronAudioProcessorEditor::ThemeButton::paintButton(juce::Graphics& g,bool over,bool){const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);const auto r=getLocalBounds().toFloat().reduced(6.0f);g.setColour(fg.withAlpha(over?1.0f:0.8f));if(dark_){const auto c=r.getCentre();g.drawEllipse(r.reduced(5.0f),1.0f);for(int i=0;i<8;++i){const float a=pi*0.25f*i;const auto a0=c+juce::Point<float>(std::cos(a),std::sin(a))*((r.getWidth()-10.0f)*0.38f);const auto a1=c+juce::Point<float>(std::cos(a),std::sin(a))*((r.getWidth()-10.0f)*0.52f);g.drawLine({a0,a1},1.0f);}}else{auto moon=r.reduced(5.0f);g.drawEllipse(moon,1.0f);g.setColour(dark_?juce::Colour(0xff0a0a0a):juce::Colours::white);g.fillEllipse(moon.translated(moon.getWidth()*0.34f,-moon.getHeight()*0.12f));}}
void MadronAudioProcessorEditor::MixLookAndFeel::drawLinearSlider(juce::Graphics& g,int x,int y,int w,int h,float pos,float,float,const juce::Slider::SliderStyle,juce::Slider&){const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);const float cy=static_cast<float>(y+h)*0.5f;g.setColour(fg.withAlpha(0.76f));g.drawLine(static_cast<float>(x),cy,static_cast<float>(x+w),cy,1.0f);g.setColour(dark_?juce::Colour(0xff0a0a0a):juce::Colours::white);g.fillEllipse(pos-4.5f,cy-4.5f,9.0f,9.0f);g.setColour(fg);g.drawEllipse(pos-4.5f,cy-4.5f,9.0f,9.0f,1.0f);}
MadronAudioProcessorEditor::MadronAudioProcessorEditor(MadronAudioProcessor& p):AudioProcessorEditor(&p),processor_(p) {auto typeface=juce::Typeface::createSystemTypefaceFor(BinaryData::GowunBatangRegular_ttf,BinaryData::GowunBatangRegular_ttfSize);font_=juce::Font(juce::FontOptions(typeface));lucky_.setDisplayFont(font_);mix_.setLookAndFeel(&mixLook_);mix_.setSliderStyle(juce::Slider::LinearHorizontal);mix_.setTextBoxStyle(juce::Slider::NoTextBox,false,0,0);mix_.setRange(0.0,1.0,0.0001);mix_.setDoubleClickReturnValue(true,0.5);mix_.setValue(processor_.globalWet(),juce::dontSendNotification);mix_.setName("Mix");mix_.setDescription("Global dry wet mix");mix_.onValueChange=[this]{processor_.setGlobalWet(static_cast<float>(mix_.getValue()));};lucky_.onClick=[this]{processor_.rollRecipe();};theme_.onClick=[this]{processor_.setThemeDark(!processor_.isThemeDark());};lucky_.setName("I'm Feeling Lucky");theme_.setName("Theme");addAndMakeVisible(lucky_);addAndMakeVisible(theme_);addAndMakeVisible(mix_);resetParticles();setSize(500,330);startTimerHz(30);}
void MadronAudioProcessorEditor::resetParticles()noexcept{for(std::size_t i=0;i<particles_.size();++i){const float q=static_cast<float>((i*37)%97)/97.0f;particles_[i]={0.3f+0.4f*q,0.42f+0.16f*static_cast<float>((i*17)%53)/53.0f,(q-0.5f)*0.0012f,0.0003f+0.0007f*static_cast<float>((i*13)%41)/41.0f,q,static_cast<float>(i)*0.37f};}}
void MadronAudioProcessorEditor::timerCallback(){dark_=processor_.isThemeDark();const bool active=processor_.isRecipeActive();if(active&&!lastActive_)resetParticles();lastActive_=active;lucky_.setActive(active);lucky_.setDark(dark_);theme_.setDark(dark_);mixLook_.setDark(dark_);const auto hostMix=processor_.globalWet();if(std::abs(mix_.getValue()-hostMix)>0.0001)mix_.setValue(hostMix,juce::dontSendNotification);if(active)for(auto& p:particles_){p.x+=p.vx;p.y+=p.vy;p.life+=0.0028f;if(p.life>1.0f){p.life=0.0f;p.x=0.35f+0.3f*std::sin(p.phase);p.y=0.46f;p.phase+=0.71f;}}repaint();}
void MadronAudioProcessorEditor::drawLogo(juce::Graphics& g,juce::Rectangle<float> area,juce::Colour colour)const{g.setColour(colour);g.setFont(font_.withHeight(25.0f));const juce::String text="madron";float widths[6]{};float total=0.0f;for(int i=0;i<6;++i){widths[i]=font_.getStringWidthFloat(text.substring(i,i+1));total+=widths[i];}const float tracking=8.0f,groupGap=15.0f;total+=tracking*5.0f+groupGap;float x=area.getCentreX()-total*0.5f;const float y=area.getCentreY()-font_.getHeight()*0.35f;for(int i=0;i<6;++i){g.drawText(text.substring(i,i+1),x,y,widths[i]+1.0f,font_.getHeight(),juce::Justification::centredLeft,false);x+=widths[i]+tracking+(i==2?groupGap:0.0f);}}
void MadronAudioProcessorEditor::paint(juce::Graphics& g){const auto bg=dark_?juce::Colour(0xff0a0a0a):juce::Colours::white;const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);g.fillAll(bg);drawLogo(g,getLocalBounds().toFloat().withTop(85.0f).withHeight(60.0f),fg);if(lastActive_){const auto bounds=lucky_.getBounds().toFloat();for(const auto& p:particles_){const float alpha=0.16f*(1.0f-std::abs(p.life*2.0f-1.0f));g.setColour(fg.withAlpha(alpha));g.fillEllipse(bounds.getX()+p.x*bounds.getWidth(),bounds.getY()+p.y*bounds.getHeight(),1.5f,1.5f);}}}
void MadronAudioProcessorEditor::resized(){auto r=getLocalBounds();theme_.setBounds(r.getRight()-42,12,30,30);lucky_.setBounds((getWidth()-190)/2,155,190,38);mix_.setBounds((getWidth()-180)/2,255,180,24);}
